      "note": "表示动作开始，常带突然性或自然发生感。",
      "contrast": "出す＝突然开始（常是不受控制的事）；始める＝一般的开始，可用于有计划的动作。",
      "promptZh": "突然下起雨来了。",
      "answerJa": "雨が急に降り出しました。",
