      "level": "N4",
      "group": "n4-voice",
      "pattern": "使役形 / 〜させる",
      "meaningZh": "让……；使……",
      "formation": "五段：未然形+せる；一段：去る+させる；する→させる；来る→来させる",
      "note": "表示让某人做事或使某种情况发生。",
      "contrast": "使役（読ませる）＝让别人做；使役受身（読ませられる）＝自己被迫做。",
