      "group": "n4-appearance",
      "pattern": "〜そうに / 〜そうな",
      "meaningZh": "看起来……地/的",
      "formation": "そうに + V；そうな + N",
      "note": "そうだ的副词/连体形。",
      "contrast": "そうな修饰名词（おいしそうなケーキ）；そうに修饰动词（楽しそうに遊ぶ）。",
