      "formation": "V普通形 / N + の + ついでに",
      "note": "表示利用做某事的机会，顺便做另一件事。",
      "contrast": "ついでに＝利用做A的机会顺便做B；ながら＝同时做两件事。",
      "promptZh": "买东西时顺便去了趟邮局。",
