      "note": "降低自己的动作以表示对对方的尊敬，常用于为对方做事的场合。更谦逊的说法是「お／ご〜いたす」。",
      "contrast": "お〜する是谦让语（我为您做）；お〜になる是尊敬语（您做）。",
      "promptZh": "我来帮您拿行李。",
